window.kbPageData["views/entry/k-11f1ec7cdbac02f0"] = {"key":"entry/k-11f1ec7cdbac02f0","state":{"route":"entry/k-11f1ec7cdbac02f0"},"node":{"id":"k-11f1ec7cdbac02f0","mode":"k","title":"年均增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["年均增长率的复合计算公式","年均增速等于末期量与基期量之比开间隔年数次方再减一","年均增长率等于末期量与基期量之比的年数次方根减一"],"qs":["国考 2023 行政执法 行测#114","江苏 2024 A类 行测#133","江苏 2025 B类 行测#129"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":3,"repeatPositions":0,"directorySummary":"年均增长率是使基期值按同一比率逐年复合增长至末期值的年增长率。基期值和末期值均为正时，年均增长率等于末期值与基期值之比的 n 次方根减 1，n 为两期之间的年度间隔数。","review":{"definition":"年均增长率是使基期值按同一比率逐年复合增长至末期值的年增长率。基期值和末期值均为正时，年均增长率等于末期值与基期值之比的 n 次方根减 1，n 为两期之间的年度间隔数。","explanation":"第129题按2016年至2023年各年的同比增长计算，以2015年为基期、2023年为末期，共8个年度间隔。三项指标的间隔数相同，开同次方根再减1会保持比值的大小顺序。应缴税费的末期值与基期值之比为5.9÷3.9，营业收入为85.7÷45.5，利润总额为4.6÷2.3，三者依次增大，因此 V₃＜V₁＜V₂，选A。","references":[],"evidence":"我国国有企业营业收入、利润总额和应缴税费年均增速","disposition":"独立词条","basis":"据原题和解析编释。","title":"年均增长率","related":[],"examFocus":{"江苏 2024 A类 行测#133":"增长年数相同，比较企业数、用户数和人均年消费额各自的末期量与基期量之比即可判断年均增速的高低。","江苏 2025 B类 行测#129":"核对年均增速所用的基期和末期，再比较营业收入、利润总额和应缴税费各自的末期量与基期量之比。"}},"readings":[{"origin":"k-11f1ec7cdbac02f0","title":"年均增长率","qs":["江苏 2025 B类 行测#129"],"definition":"年均增长率是使基期值按同一比率逐年复合增长至末期值的年增长率。基期值和末期值均为正时，年均增长率等于末期值与基期值之比的 n 次方根减 1，n 为两期之间的年度间隔数。","explanation":"第129题按2016年至2023年各年的同比增长计算，以2015年为基期、2023年为末期，共8个年度间隔。三项指标的间隔数相同，开同次方根再减1会保持比值的大小顺序。应缴税费的末期值与基期值之比为5.9÷3.9，营业收入为85.7÷45.5，利润总额为4.6÷2.3，三者依次增大，因此 V₃＜V₁＜V₂，选A。","evidence":"我国国有企业营业收入、利润总额和应缴税费年均增速","doubt":"","references":[]},{"origin":"k-3a09f60b7757a85b","title":"年均增长率","qs":["国考 2023 行政执法 行测#114"],"definition":"年均增长率是从基期到末期按复合增长折算的等效年度增长率。基期量和末期量均为正时，年均增长率等于（末期量÷基期量）的 1/n 次方减 1，其中 n 为末期与基期相隔的年数。","explanation":"把基期量连续 n 年按同一增长率折算，就得到末期量，因此由首末期量之比开 n 次方可得每年的增长倍数。本题以 2016 年为基期、2021 年为末期，经历 5 个年度增长间隔，n 取 5。","evidence":"（n为年份差）","doubt":"","references":[]},{"origin":"k-ca7cacfa5486b222","title":"年均增长率","qs":["江苏 2024 A类 行测#133"],"definition":"年均增长率是使基期量经过若干年按同一比例复合增长后达到末期量的增长率。基期量和末期量均为正时，将末期量除以基期量，取两期年份差次方根，再减去 1。","explanation":"2019 年到 2022 年相隔 3 年。三个指标都取三次方根再减 1，这两步都保持大小顺序，因此直接比较末期量与基期量之比即可。企业数之比约为 3.29（18700÷5684），用户数之比为 1.88（4.7÷2.5），人均年消费额之比约为 4.20（7450÷1775）。所以用户数年均增速最低，人均年消费额年均增速最高，即 V₂＜V₁＜V₃，符合 B 项。","evidence":"当年\n\n份差相同时，直接比较","doubt":"","references":[]}]},"questions":{"国考 2023 行政执法 行测#114":{"paper":"国考 2023 行政执法 行测","n":114,"mod":"资料分析","src":["857378cf496f27296500.pdf",22],"asrc":["d23139fe5a0fb3115135.pdf",37],"card":"d13bdb97632bd6b06c737d10","links":[{"id":"k-11f1ec7cdbac02f0","role":"解题依据","why":"该复合增长公式说明年均增速与首末期产量及间隔年数的关系。"}]},"江苏 2024 A类 行测#133":{"paper":"江苏 2024 A类 行测","n":133,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",26],"asrc":["0126a1c8aceee632ea2b.pdf",41],"card":"68e7413732d667e132559714","links":[{"id":"k-11f1ec7cdbac02f0","role":"直接考查","why":"三个指标的年份差相同，开方和减一均保持末期量与基期量之比的大小顺序。"}]},"江苏 2025 B类 行测#129":{"paper":"江苏 2025 B类 行测","n":129,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",26],"asrc":["f2ff67a0f2a2f7e8e926.pdf",43],"card":"1fd861d1f14f1d14302cbb3b","links":[{"id":"k-11f1ec7cdbac02f0","role":"解题依据","why":"年均增长率等于末期值与基期值之比的 n 次方根减一，n 为两期之间的增长间隔数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-11f1ec7cdbac02f0":[["国考 2023 行政执法 行测#114"],["江苏 2024 A类 行测#133"],["江苏 2025 B类 行测#129"]]}};
